    if poisson_norm < 0.97:
        raise ValueError("Poisson constraint not satisfied")

    return denoised

def apply_knn_normalization(X, knn, t, n_pca, solver, decay, knn_max, n_jobs):
    if n_pca > 0:
        X = PCA(n_components=n_pca).fit_transform(X)

    distances = np.zeros((X.shape[0], X.shape[0]))
    knn_model = NearestNeighbors(n_neighbors=knn, metric='euclidean').fit(X)
    for i in range(X.shape[0]):
        neighbors = knn_model.kneighbors_distances[i]
        neighbors[neighbors == 0] = float('inf')
        distances[i, :] = np.exp(-neighbors * t)

    return np.dot(distances, X) / np.sum(distances, axis=1, keepdims=True)

